<script setup>
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {apiRequest} from '../../services/apiClient'
import {referenceCurrencyService} from '../../services/referenceCurrencyService'
import {cashManagementService} from './service'
import BaseButton from '../../components/ui/BaseButton.vue'
import BaseInput from '../../components/ui/BaseInput.vue'
import BaseModal from '../../components/ui/BaseModal.vue'
const route=useRoute(),rows=ref([]),vaultOptions=ref([]),currencyOptions=ref([]),ownerOptions=ref([]),loading=ref(false),error=ref(''),search=ref(''),action=ref(''),active=ref(null),form=ref({}),modalOpen=ref(false),ownerQueries=ref({owner_user_id:'',custodian_user_id:''}),ownerResults=ref({owner_user_id:[],custodian_user_id:[]}),ownerOpenKey=ref(''),ownerLoading=ref({owner_user_id:false,custodian_user_id:false}),currencyLoading=ref(false),vaultLoading=ref(false),balancesModal=ref(false),balanceRows=ref([]),balanceVault=ref(null),balanceStatus=ref(''),balanceLoading=ref(false),balanceError=ref('')
const section=computed(()=>route.meta.cashManagementSection||'vaults'),title=computed(()=>({vaults:'Vaults',transfers:'Transfers','opening-balances':'Opening Balances',reconciliations:'Reconciliations'}[section.value]))
const paths={vaults:'/cash-management/vaults',transfers:'/cash-management/transfers','opening-balances':'/cash-management/opening-balances',reconciliations:'/cash-management/reconciliations'}
const shown=computed(()=>rows.value.filter(r=>!search.value||Object.values(r).some(v=>String(v??'').toLowerCase().includes(search.value.toLowerCase()))))
const cols=computed(()=>{let k=section.value==='vaults'?['vault_code','vault_name','vault_type','status','id']:section.value==='transfers'?['transfer_code','source_vault_id','dest_vault_id','initiated_amount','status','id']:section.value==='opening-balances'?['vault_id','currency_id','opening_balance','status','id']:['vault_id','currency_id','business_date','counted_physical_amount','status','id'];return k.filter(x=>rows.value.some(r=>x in r)).slice(0,5)})
const defs=computed(()=>section.value==='vaults'?(form.value.vault_type==='BRANCH_VAULT'?[['vault_type','Vault type'],['vault_code','Vault code'],['vault_name','Vault name'],['custodian_user_id','Custodian']]:[['vault_type','Vault type'],['vault_code','Vault code'],['vault_name','Vault name'],['owner_user_id','Owner']]):section.value==='transfers'?[['source_vault_id','Source vault'],['dest_vault_id','Destination vault'],['currency_id','Currency'],['transfer_type','Transfer type'],['initiated_amount','Amount'],['tolerance_amount','Tolerance'],['remarks','Remarks']]:section.value==='opening-balances'?[['vault_id','Vault'],['currency_id','Currency'],['opening_balance','Opening balance'],['notes','Notes']]:[['vault_id','Vault'],['currency_id','Currency'],['business_date','Business date'],['counted_physical_amount','Counted amount'],['notes','Notes']])
function normalizeList(r){return Array.isArray(r)?r:Array.isArray(r?.data)?r.data:Array.isArray(r?.data?.items)?r.data.items:Array.isArray(r?.items)?r.items:[]}
async function load(){loading.value=true;error.value='';try{let r=await cashManagementService.list(paths[section.value]);rows.value=normalizeList(r)}catch(e){error.value=e?.message||'Could not load records';rows.value=[]}finally{loading.value=false}}
function rid(r){return r?.id||r?.uuid||r?.transfer_id||r?.opening_balance_id||r?.reconciliation_id}
function vaultName(v){return v?.vault_name||v?.name||v?.vault_code||String(v?.id??'')}
function currencyName(c){return [c?.code,c?.name].filter(Boolean).join(' — ')||String(c?.id??'')}
async function loadVaults(){vaultLoading.value=true;try{const res=await apiRequest('cash-management/vaults');vaultOptions.value=normalizeList(res)}catch(e){error.value=e?.message||'Could not load vault options'}finally{vaultLoading.value=false}}
async function viewOpeningBalances(v){balanceVault.value=v;balanceStatus.value='';balancesModal.value=true;await loadOpeningBalances()}
async function loadOpeningBalances(){if(!balanceVault.value?.id)return;balanceLoading.value=true;balanceError.value='';try{const params=new URLSearchParams({vaultId:String(balanceVault.value.id)});if(balanceStatus.value)params.set('status',balanceStatus.value);const res=await apiRequest('cash-management/opening-balances?'+params.toString());balanceRows.value=normalizeList(res)}catch(e){balanceError.value=e?.message||'Could not load opening balances';balanceRows.value=[]}finally{balanceLoading.value=false}}
async function loadCurrencies(){currencyLoading.value=true;try{const res=await referenceCurrencyService.list({page:1,page_size:100});currencyOptions.value=(Array.isArray(res?.data)?res.data:normalizeList(res)).filter(c=>c.is_active!==false)}catch(e){error.value=e?.message||'Could not load currencies'}finally{currencyLoading.value=false}}
async function searchOwners(key,q=''){ownerLoading.value[key]=true;try{const res=await apiRequest('users?page=1&search='+encodeURIComponent(q));ownerResults.value[key]=normalizeList(res)}catch(e){error.value=e?.message||'Unable to search users'}finally{ownerLoading.value[key]=false}}
function userLabel(u){return [u?.first_name,u?.middle_name,u?.last_name].filter(Boolean).join(' ')||u?.username||u?.email||String(u?.id??'User')}
function chooseOwner(key,u){form.value[key]=u?.id;ownerQueries.value[key]=userLabel(u);ownerOpenKey.value=''}
function open(m,r){action.value=m;modalOpen.value=true;active.value=r||null;ownerQueries.value={owner_user_id:'',custodian_user_id:''};ownerOpenKey.value='';form.value=r?{...r}:{vault_type:'TELLER_TILL',vault_code:'',vault_name:'',owner_user_id:'',custodian_user_id:'',source_vault_id:'',dest_vault_id:'',currency_id:'',transfer_type:'VAULT_TO_TELLER',initiated_amount:'',tolerance_amount:'',remarks:'',opening_balance:'',notes:'',business_date:'',counted_physical_amount:''};if(r){const v=vaultOptions.value.find(x=>String(x.id)===String(r.vault_id||r.source_vault_id));if(v)form.value._vaultLabel=vaultName(v);const c=currencyOptions.value.find(x=>String(x.id)===String(r.currency_id));if(c)form.value._currencyLabel=currencyName(c);for(const key of ['owner_user_id','custodian_user_id'])if(r[key])searchOwners(key,String(r[key]).trim()).then(()=>{const u=ownerResults.value[key].find(u=>String(u.id)===String(r[key]));if(u)ownerQueries.value[key]=userLabel(u)})}}
async function save(){loading.value=true;try{let payload,endpoint=paths[section.value];if(section.value==='vaults'){payload={vault_type:form.value.vault_type,vault_code:form.value.vault_code,vault_name:form.value.vault_name,...(form.value.vault_type==='BRANCH_VAULT'?{custodian_user_id:Number(form.value.custodian_user_id)}:{owner_user_id:Number(form.value.owner_user_id)})}}else if(section.value==='opening-balances'){endpoint='/cash-management/vaults/'+encodeURIComponent(form.value.vault_id)+'/opening-balances';payload={currency_id:form.value.currency_id,opening_balance:Number(form.value.opening_balance),notes:form.value.notes}}else{payload=Object.fromEntries(defs.value.map(([key])=>[key,form.value[key]]))}if(action.value==='edit')await cashManagementService.patch(endpoint+'/'+encodeURIComponent(rid(active.value)),payload);else await cashManagementService.post(endpoint,payload);action.value='';modalOpen.value=false;await load()}catch(e){error.value=e?.message||'Save failed'}finally{loading.value=false}}
async function operate(t,r){let id=encodeURIComponent(rid(r)),p='',b={};if(t==='receive'){p='/cash-management/transfers/'+id+'/receive';b={received_amount:r.initiated_amount||10000,receipt_notes:'Cash counted and matched with transfer slip'}}else if(t==='accept'){p='/cash-management/opening-balances/'+id+'/accept';b={counted_amount:Number(r.opening_balance)}}else if(t==='reject'){p='/cash-management/opening-balances/'+id+'/reject';b={reason:'Received amount does not match the handover slip'}}else p='/cash-management/reconciliations/'+id+'/approve';loading.value=true;error.value='';try{await cashManagementService.post(p,b);await load()}catch(e){error.value=e?.message||'Action failed'}finally{loading.value=false}}
watch(section,()=>{action.value='';load()});onMounted(async()=>{await Promise.all([load(),loadVaults(),loadCurrencies()])})
</script>
<template><section class="module-page"><div class="module-page-intro"><div><h2>{{title}}</h2><p class="module-description">List records first, then add, edit or process them.</p></div><BaseButton class="module-primary-btn" @click="open('add')">＋ Add Record</BaseButton></div><div class="module-stat-row"><div class="module-stat-card"><span>Total records</span><strong>{{rows.length}}</strong></div><div class="module-stat-card"><span>Filtered records</span><strong>{{shown.length}}</strong></div></div><section class="module-panel"><div class="module-panel-header"><h3>{{title}} register</h3><label class="module-search"><BaseInput v-model="search" placeholder="Search records..." size="sm"/></label><BaseButton variant="secondary" size="sm" @click="load">Refresh</BaseButton></div><p v-if="error" class="cash-error">{{error}}</p><div class="module-table-wrap"><table class="module-table"><thead><tr><th v-for="c in cols" :key="c">{{c.replaceAll('_',' ')}}</th><th>Actions</th></tr></thead><tbody><tr v-if="loading"><td :colspan="cols.length+1" class="module-empty-state">Loading…</td></tr><tr v-else-if="!shown.length"><td :colspan="cols.length+1" class="module-empty-state">No records found.</td></tr><tr v-for="r in shown" :key="rid(r)"><td v-for="c in cols" :key="c">{{c==='vault_id'?vaultName(vaultOptions.find(v=>String(v.id)===String(r[c]))||r):c==='currency_id'?currencyName(currencyOptions.find(v=>String(v.id)===String(r[c]))||r):r[c]??'—'}}</td><td><div class="cash-actions"><BaseButton variant="secondary" size="sm" @click="open('view',r)">View</BaseButton><BaseButton variant="secondary" size="sm" @click="open('edit',r)">Edit</BaseButton><BaseButton v-if="section==='vaults'" variant="secondary" size="sm" @click="viewOpeningBalances(r)">Opening balances</BaseButton><BaseButton v-if="section==='transfers'" variant="secondary" size="sm" @click="operate('receive',r)">Receive</BaseButton><BaseButton v-if="section==='opening-balances'" variant="secondary" size="sm" @click="operate('accept',r)">Accept</BaseButton><BaseButton v-if="section==='opening-balances'" variant="danger" size="sm" @click="operate('reject',r)">Reject</BaseButton><BaseButton v-if="section==='reconciliations'" variant="secondary" size="sm" @click="operate('approve',r)">Approve</BaseButton></div></td></tr></tbody></table></div><div class="module-table-footer">Showing {{shown.length}} of {{rows.length}}</div></section><BaseModal v-model="modalOpen" :title="action==='view'?'View record':action==='edit'?'Edit record':'Add record'" size="lg"><form class="cash-form" @submit.prevent="save"><div v-for="([key,label]) in defs" :key="key" class="cash-field"><label>{{label}}</label><template v-if="key==='owner_user_id'||key==='custodian_user_id'"><div class="cash-owner-wrap"><input v-model="ownerQueries[key]" type="search" :disabled="action==='view'" placeholder="Search users by name, email..." @focus="ownerOpenKey=key;searchOwners(key,ownerQueries[key])" @input="ownerOpenKey=key;searchOwners(key,ownerQueries[key])" @blur="setTimeout(()=>{if(ownerOpenKey===key)ownerOpenKey=''},180)"/><div v-if="ownerOpenKey===key&&action!=='view'" class="cash-options"><p v-if="ownerLoading[key]">Searching users…</p><button v-for="u in ownerResults[key]" :key="u.id" type="button" @mousedown.prevent="chooseOwner(key,u)"><strong>{{userLabel(u)}}</strong><small>{{u.email||u.phone_number||('User ID '+u.id)}}</small></button><p v-if="!ownerLoading[key]&&!ownerResults[key].length">No users found.</p></div></div></template><template v-else-if="key==='vault_id'||key==='source_vault_id'||key==='dest_vault_id'"><select v-model="form[key]" :disabled="action==='view'||vaultLoading" required><option value="">{{vaultLoading?'Loading vaults…':'Select vault'}}</option><option v-for="v in vaultOptions" :key="v.id" :value="v.id">{{vaultName(v)}}</option></select></template><template v-else-if="key==='currency_id'"><select v-model="form[key]" :disabled="action==='view'||currencyLoading" required><option value="">{{currencyLoading?'Loading currencies…':'Select currency'}}</option><option v-for="c in currencyOptions" :key="c.id" :value="c.id">{{currencyName(c)}}</option></select></template><template v-else-if="key==='vault_type'"><select v-model="form[key]" :disabled="action==='view'" required><option value="TELLER_TILL">Teller Till</option><option value="BRANCH_VAULT">Branch Vault</option></select></template><template v-else><input v-model="form[key]" :disabled="action==='view'" :type="['initiated_amount','tolerance_amount','opening_balance','counted_physical_amount'].includes(key)?'number':key==='business_date'?'date':'text'"/></template></div><div class="cash-submit"><BaseButton v-if="action!=='view'" type="submit" :disabled="loading">{{loading?'Saving…':'Save'}}</BaseButton></div></form></BaseModal><BaseModal v-model="balancesModal" title="Vault opening balances" size="lg"><div class="cash-form balance-view"><div class="balance-toolbar"><div><strong>{{balanceVault?.vault_name||balanceVault?.vault_code||'Vault'}}</strong><small>{{balanceVault?.id}}</small></div><select v-model="balanceStatus" @change="loadOpeningBalances"><option value="">All statuses</option><option value="PENDING">Pending</option><option value="ACCEPTED">Accepted</option><option value="REJECTED">Rejected</option></select><BaseButton variant="secondary" size="sm" @click="loadOpeningBalances">Refresh</BaseButton></div><p v-if="balanceError" class="cash-error">{{balanceError}}</p><div class="module-table-wrap"><table class="module-table"><thead><tr><th>Currency</th><th>Opening balance</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr v-if="balanceLoading"><td colspan="4" class="module-empty-state">Loading…</td></tr><tr v-else-if="!balanceRows.length"><td colspan="4" class="module-empty-state">No opening balances found.</td></tr><tr v-for="b in balanceRows" :key="rid(b)"><td>{{currencyName(currencyOptions.find(c=>String(c.id)===String(b.currency_id))||{id:b.currency_id})}}</td><td>{{b.opening_balance??'—'}}</td><td>{{b.status??'—'}}</td><td>{{b.notes??'—'}}</td></tr></tbody></table></div></div></BaseModal></section></template>
<style scoped>.cash-actions{display:flex;gap:6px;flex-wrap:wrap;white-space:nowrap}.cash-form{padding:20px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.cash-field{display:flex;flex-direction:column;gap:6px;min-width:0}.cash-field input,.cash-field select{padding:9px;border:1px solid var(--border-color,#dbe2ea);border-radius:7px;background:white;min-width:0}.cash-owner-wrap{position:relative}.cash-owner-wrap input{width:100%;box-sizing:border-box}.cash-options{position:absolute;z-index:12;top:100%;left:0;right:0;max-height:230px;overflow-y:auto;background:white;border:1px solid #dbe2ea;border-radius:8px;box-shadow:0 8px 22px #1b30451c}.cash-options button{display:flex;flex-direction:column;align-items:flex-start;width:100%;padding:9px 12px;border:0;border-bottom:1px solid #eef1f4;background:white;cursor:pointer;text-align:left}.cash-options button:hover{background:#f3f7fb}.cash-options small,.cash-options p{margin:0;padding:8px 12px;color:#77869a;font-size:11px}.cash-submit{grid-column:1/-1;display:flex;justify-content:flex-end}.balance-view{display:block}.balance-toolbar{display:flex;align-items:center;gap:10px;justify-content:space-between;margin-bottom:14px}.balance-toolbar div{display:flex;flex-direction:column;gap:3px}.balance-toolbar small{font-size:11px;color:#77869a}.balance-toolbar select{padding:8px;border:1px solid var(--border-color,#dbe2ea);border-radius:7px;background:white}@media(max-width:650px){.cash-form{grid-template-columns:1fr}}</style>